extra_style:
.text-success{color:var(--success);}
.text-primary{color:var(--amber);}
.text-info{color:var(--ink-2);}
.text-warning{color:var(--amber);}
.text-danger{color:var(--red);}

#devices-container{display:flex;flex-wrap:wrap;gap:1rem;}
#devices-container>.col-md-4{flex:1 1 240px;}
#devices-container>.col-12{flex:1 1 100%;}

.card{border:1px solid var(--border);border-radius:4px;background:var(--panel);}
.card-body{padding:1rem;}
.card-title{font-family:'JetBrains Mono',monospace;font-size:13px;font-weight:600;color:var(--ink);margin:0 0 .4rem;display:flex;align-items:center;gap:.45rem;}
.card-text{font-size:11.5px;margin:0 0 .7rem;}
.device-card{cursor:pointer;transition:transform .15s ease;}
.device-card:hover{transform:translateY(-2px);}
.device-card.selected{border-color:var(--amber);border-width:2px;}

.status-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--ink-3);margin-right:.4rem;}
.status-dot.connected{background:var(--success);}
.status-dot.default{background:var(--amber);}
.status-dot.disconnected{background:var(--red);}

.btn-outline-primary{display:inline-flex;align-items:center;justify-content:center;font-size:11.5px;font-weight:600;padding:.4rem .8rem;border-radius:4px;border:1px solid var(--amber);background:transparent;color:var(--amber);cursor:pointer;font-family:'IBM Plex Sans',sans-serif;}
.btn-outline-primary:hover{background:var(--amber-dim);}

.no-microphones{display:flex;flex-direction:column;align-items:center;justify-content:center;padding:2rem;text-align:center;background:var(--panel-2);border-radius:4px;border:1px solid var(--border);}
.no-microphones i{font-size:3rem;margin-bottom:1rem;color:var(--ink-3);}

#spectrogram-container{position:relative;height:200px;margin-top:1rem;border:1px solid var(--border);border-radius:4px;overflow:hidden;background:var(--panel-2);}
#spectrogram-container canvas{width:100%;height:100%;}

script:
document.addEventListener('DOMContentLoaded', function () {
  // DOM Elements
  const browserAlert = document.getElementById('browser-alert');
  const browserMessage = document.getElementById('browser-message');
  const devicesContainer = document.getElementById('devices-container');
  const deviceDetails = document.getElementById('device-details');
  const refreshButton = document.getElementById('refresh-button');
  const testButton = document.getElementById('test-button');
  const stopButton = document.getElementById('stop-button');
  const spectrogram = document.getElementById('spectrogram');

  // Variables for audio handling
  let audioContext;
  let analyser;
  let microphone;
  let spectrogramCtx;
  let activeDeviceId = null;
  let audioStream = null;
  let animationFrame = null;

  // Initialize the canvas
  spectrogramCtx = spectrogram.getContext('2d');

  // Function to resize the canvas
  function resizeCanvas() {
    spectrogram.width = spectrogram.offsetWidth;
    spectrogram.height = spectrogram.offsetHeight;
  }

  // Call resize initially and on window resize
  resizeCanvas();
  window.addEventListener('resize', resizeCanvas);

  // Check browser compatibility for media devices
  if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) {
    browserMessage.innerHTML = `
                  <i class="bi bi-exclamation-triangle-fill me-2 text-danger"></i>
                  Your browser doesn't support the required features to detect audio devices. Please use a modern browser like Chrome, Firefox, or Edge.
              `;
    browserAlert.classList.remove('alert-info');
    browserAlert.classList.add('alert-danger');
    return;
  }

  // Function to fetch and display all audio input devices
  function getAudioDevices() {
    browserMessage.innerHTML = `
                  <i class="bi bi-info-circle-fill me-2"></i>
                  Detecting your microphones. Please wait...
              `;

    // Clear existing devices
    devicesContainer.innerHTML = '';

    // Flag to check if we need permission first
    let needsPermission = true;

    // First, enumerate to check if we need permission
    navigator.mediaDevices.enumerateDevices()
      .then(devices => {
        const mics = devices.filter(device => device.kind === 'audioinput');

        // If we already have labels, we don't need to request permission
        if (mics.length > 0 && mics.some(mic => mic.label)) {
          needsPermission = false;
          displayDevices(mics);
        } else if (mics.length === 0) {
          // No microphones found
          displayNoMicrophones();
          needsPermission = false;
        }

        // If we need permission, request it
        if (needsPermission) {
          browserMessage.innerHTML = `
                              <i class="bi bi-info-circle-fill me-2"></i>
                              Please allow access to your microphone when prompted.
                          `;

          return navigator.mediaDevices.getUserMedia({audio: true})
            .then(stream => {
              // Stop the stream immediately, we just needed permission
              stream.getTracks().forEach(track => track.stop());

              // Now enumerate devices again with permission
              return navigator.mediaDevices.enumerateDevices();
            })
            .then(devices => {
              const mics = devices.filter(device => device.kind === 'audioinput');
              displayDevices(mics);
            });
        }
      })
      .catch(error => {
        console.error('Error enumerating devices:', error);
        browserMessage.innerHTML = `
                          <i class="bi bi-exclamation-triangle-fill me-2 text-danger"></i>
                          Error accessing your audio devices: ${error.message}. Please ensure you've granted permission to access your microphone.
                      `;
        browserAlert.classList.remove('alert-info');
        browserAlert.classList.add('alert-danger');
      });
  }

  // Function to display no microphones message
  function displayNoMicrophones() {
    devicesContainer.innerHTML = `
                  <div class="col-12">
                      <div class="no-microphones">
                          <i class="bi bi-mic-mute"></i>
                          <h4>No Microphones Detected</h4>
                          <p>We couldn't find any microphones connected to your device. Please connect a microphone and click the Refresh button.</p>
                      </div>
                  </div>
              `;

    browserMessage.innerHTML = `
                  <i class="bi bi-exclamation-triangle-fill me-2 text-warning"></i>
                  No microphones detected. Please connect a microphone and refresh.
              `;
    browserAlert.classList.remove('alert-info');
    browserAlert.classList.add('alert-warning');

    // Hide device details
    deviceDetails.classList.add('d-none');
  }

  // Function to display found devices
  function displayDevices(mics) {
    if (mics.length === 0) {
      displayNoMicrophones();
      return;
    }

    browserMessage.innerHTML = `
                  <i class="bi bi-check-circle-fill me-2 text-success"></i>
                  Found ${mics.length} microphone${mics.length > 1 ? 's' : ''}. Click on a microphone to view detailed information.
              `;
    browserAlert.classList.remove('alert-info');
    browserAlert.classList.add('alert-success');

    // Create card for each device
    mics.forEach((device, index) => {
      const deviceCard = document.createElement('div');
      deviceCard.className = 'col-md-4';
      deviceCard.innerHTML = `
                      <div class="card device-card" data-device-id="${device.deviceId}">
                          <div class="card-body">
                              <h5 class="card-title">
                                  <span class="status-dot connected"></span>
                                  ${device.label || `Microphone ${index + 1}`}
                              </h5>
                              <p class="card-text text-muted">
                                  ${device.deviceId.substring(0, 8)}...
                              </p>
                              <button class="btn btn-outline-primary btn-sm">
                                  <i class="bi bi-info-circle me-1"></i>View Details
                              </button>
                          </div>
                      </div>
                  `;
      devicesContainer.appendChild(deviceCard);

      // Add click event to the card
      const card = deviceCard.querySelector('.device-card');
      card.addEventListener('click', () => {
        // Remove selected class from all cards
        document.querySelectorAll('.device-card').forEach(c => {
          c.classList.remove('selected');
        });

        // Add selected class to this card
        card.classList.add('selected');

        // Show device details
        showDeviceDetails(device);
      });
    });
  }

  // Function to show device details
  function showDeviceDetails(device) {
    // Set active device ID
    activeDeviceId = device.deviceId;

    // Show the details card
    deviceDetails.classList.remove('d-none');

    // Update the device name
    document.getElementById('selected-device-name').textContent = device.label || 'Unknown Microphone';

    // Update basic info
    document.getElementById('device-id').textContent = device.deviceId;
    document.getElementById('group-id').textContent = device.groupId;
    document.getElementById('is-default').textContent = 'Checking...';
    document.getElementById('device-status').innerHTML = '<span class="status-dot connected"></span> Connected';

    // Get detailed info about the device
    getDeviceDetails(device.deviceId);
  }

  // Function to get detailed device information
  function getDeviceDetails(deviceId) {
    // Reset all fields first
    document.getElementById('sample-rate').textContent = '—';
    document.getElementById('sample-size').textContent = '—';
    document.getElementById('channel-count').textContent = '—';
    document.getElementById('latency').textContent = '—';
    document.getElementById('auto-gain').textContent = '—';
    document.getElementById('echo-cancellation').textContent = '—';
    document.getElementById('noise-suppression').textContent = '—';
    document.getElementById('volume').textContent = '—';
    document.getElementById('quality-rating').textContent = '—';

    // Request access to the specific device
    navigator.mediaDevices.getUserMedia({
      audio: {
        deviceId: {exact: deviceId}
      }
    })
      .then(stream => {
        // Store the stream so we can stop it later
        if (audioStream) {
          audioStream.getTracks().forEach(track => track.stop());
        }
        audioStream = stream;

        // Get the audio track
        const track = stream.getAudioTracks()[0];

        // Get capabilities and settings
        const capabilities = track.getCapabilities ? track.getCapabilities() : {};
        const settings = track.getSettings ? track.getSettings() : {};

        // Update UI with settings
        if (settings.sampleRate) {
          document.getElementById('sample-rate').textContent = settings.sampleRate + ' Hz';
        }

        if (settings.sampleSize) {
          document.getElementById('sample-size').textContent = settings.sampleSize + ' bits';
        }

        if (settings.channelCount) {
          document.getElementById('channel-count').textContent = settings.channelCount + ' channel' + (settings.channelCount > 1 ? 's' : '');
        }

        if (settings.latency) {
          document.getElementById('latency').textContent = settings.latency + ' ms';
        }

        if (settings.autoGainControl !== undefined) {
          document.getElementById('auto-gain').textContent = settings.autoGainControl ? 'Enabled' : 'Disabled';
        }

        if (settings.echoCancellation !== undefined) {
          document.getElementById('echo-cancellation').textContent = settings.echoCancellation ? 'Enabled' : 'Disabled';
        }

        if (settings.noiseSuppression !== undefined) {
          document.getElementById('noise-suppression').textContent = settings.noiseSuppression ? 'Enabled' : 'Disabled';
        }

        // Check if this is the default device
        navigator.mediaDevices.enumerateDevices()
          .then(devices => {
            const audioInputs = devices.filter(d => d.kind === 'audioinput');

            if (audioInputs.length > 0 && audioInputs[0].deviceId === deviceId) {
              document.getElementById('is-default').innerHTML = '<span class="status-dot default"></span> Default Device';
            } else {
              document.getElementById('is-default').innerHTML = 'Not Default';
            }
          });

        // Calculate quality rating
        let qualityScore = 0;
        if (settings.channelCount && settings.channelCount >= 2) qualityScore += 1;
        if (settings.sampleRate && settings.sampleRate >= 44100) qualityScore += 1;
        if (settings.sampleSize && settings.sampleSize >= 24) qualityScore += 1;
        if (settings.autoGainControl) qualityScore += 0.5;
        if (settings.echoCancellation) qualityScore += 0.5;
        if (settings.noiseSuppression) qualityScore += 0.5;
        if (settings.latency && settings.latency < 50) qualityScore += 0.5;

        let qualityRating;
        let qualityClass;

        if (qualityScore >= 4) {
          qualityRating = 'Excellent';
          qualityClass = 'text-success';
        } else if (qualityScore >= 3) {
          qualityRating = 'Very Good';
          qualityClass = 'text-primary';
        } else if (qualityScore >= 2) {
          qualityRating = 'Good';
          qualityClass = 'text-info';
        } else if (qualityScore >= 1) {
          qualityRating = 'Fair';
          qualityClass = 'text-warning';
        } else {
          qualityRating = 'Basic';
          qualityClass = 'text-danger';
        }

        document.getElementById('quality-rating').innerHTML = `<span class="${qualityClass}">${qualityRating}</span>`;

        // Stop the stream after getting info
        stream.getTracks().forEach(track => track.stop());
        audioStream = null;
      })
      .catch(error => {
        console.error('Error getting device details:', error);
        document.getElementById('device-status').innerHTML = '<span class="status-dot disconnected"></span> Error: ' + error.message;
      });
  }

  // Function to test the microphone
  function testMicrophone() {
    if (!activeDeviceId) {
      alert('Please select a microphone first');
      return;
    }

    // Swap buttons
    testButton.classList.add('d-none');
    stopButton.classList.remove('d-none');

    // Initialize audio context (wait until user interaction)
    if (!audioContext) {
      window.AudioContext = window.AudioContext || window.webkitAudioContext;
      audioContext = new AudioContext();
    }

    // Request the selected device
    navigator.mediaDevices.getUserMedia({
      audio: {
        deviceId: {exact: activeDeviceId}
      }
    })
      .then(stream => {
        // Store the stream
        audioStream = stream;

        // Create analyzer
        analyser = audioContext.createAnalyser();
        analyser.fftSize = 2048;

        // Connect microphone to analyser
        microphone = audioContext.createMediaStreamSource(stream);
        microphone.connect(analyser);

        // Start visualization
        visualize();

        // Start monitoring volume
        startVolumeMonitoring();
      })
      .catch(error => {
        console.error('Error accessing microphone:', error);
        alert('Error accessing microphone: ' + error.message);

        // Reset buttons
        stopButton.classList.add('d-none');
        testButton.classList.remove('d-none');
      });
  }

  // Function to visualize audio
  function visualize() {
    if (!analyser) return;

    // Get the canvas dimensions
    const width = spectrogram.width;
    const height = spectrogram.height;

    // Set up the analyzer
    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    // Clear the canvas
    spectrogramCtx.clearRect(0, 0, width, height);
    spectrogramCtx.fillStyle = 'rgb(248, 249, 250)';
    spectrogramCtx.fillRect(0, 0, width, height);

    function draw() {
      if (!analyser) {
        return;
      }

      // Request next frame
      animationFrame = requestAnimationFrame(draw);

      // Get frequency data
      analyser.getByteFrequencyData(dataArray);

      // Clear canvas
      spectrogramCtx.clearRect(0, 0, width, height);
      spectrogramCtx.fillStyle = 'rgb(248, 249, 250)';
      spectrogramCtx.fillRect(0, 0, width, height);

      // Draw frequency bars
      const barWidth = width / bufferLength * 2.5;
      let x = 0;

      for (let i = 0; i < bufferLength; i++) {
        const barHeight = dataArray[i] / 255 * height;

        // Create gradient
        const gradient = spectrogramCtx.createLinearGradient(0, height, 0, height - barHeight);
        gradient.addColorStop(0, 'rgb(13, 110, 253, 0.8)');
        gradient.addColorStop(1, 'rgb(13, 110, 253, 0.2)');

        spectrogramCtx.fillStyle = gradient;
        spectrogramCtx.fillRect(x, height - barHeight, barWidth, barHeight);

        x += barWidth + 1;

        // Only draw a subset of bars for performance
        if (i > bufferLength / 4) break;
      }
    }

    draw();
  }

  // Function to monitor volume
  function startVolumeMonitoring() {
    if (!analyser) return;

    const bufferLength = analyser.frequencyBinCount;
    const dataArray = new Uint8Array(bufferLength);

    function checkVolume() {
      if (!analyser) {
        return;
      }

      // Get time domain data
      analyser.getByteTimeDomainData(dataArray);

      // Calculate volume
      let sum = 0;
      for (let i = 0; i < bufferLength; i++) {
        sum += Math.abs(dataArray[i] - 128);
      }

      const average = sum / bufferLength;
      const volume = Math.round((average / 128) * 100);

      // Update UI
      document.getElementById('volume').textContent = volume + '%';

      // Call again
      setTimeout(checkVolume, 100);
    }

    checkVolume();
  }

  // Function to stop microphone test
  function stopMicTest() {
    // Cancel animation frame
    if (animationFrame) {
      cancelAnimationFrame(animationFrame);
      animationFrame = null;
    }

    // Stop the audio stream
    if (audioStream) {
      audioStream.getTracks().forEach(track => track.stop());
      audioStream = null;
    }

    // Clean up audio nodes
    if (microphone) {
      microphone.disconnect();
      microphone = null;
    }

    analyser = null;

    // Reset buttons
    stopButton.classList.add('d-none');
    testButton.classList.remove('d-none');

    // Clear canvas
    spectrogramCtx.clearRect(0, 0, spectrogram.width, spectrogram.height);
    spectrogramCtx.fillStyle = 'rgb(248, 249, 250)';
    spectrogramCtx.fillRect(0, 0, spectrogram.width, spectrogram.height);

    // Reset volume display
    document.getElementById('volume').textContent = '—';
  }

  // Event listeners
  refreshButton.addEventListener('click', getAudioDevices);
  testButton.addEventListener('click', testMicrophone);
  stopButton.addEventListener('click', stopMicTest);

  // Initialize
  getAudioDevices();
});
